import Link from '@docusaurus/Link';
import useBaseUrl from '@docusaurus/useBaseUrl';
import type { Props } from '@theme/DocSidebar';
import clsx from 'clsx';
import { useState } from 'react';
import { groupsOf, samePath } from '../../components/docs/sidebarGroups';
import styles from './styles.module.css';

// The autogenerated sidebar with a page filter on top and the plain text docs at the bottom.
export default function DocSidebar({ sidebar, path }: Props) {
  const [query, setQuery] = useState('');
  const [closed, setClosed] = useState<Record<string, boolean>>({});
  const llms = useBaseUrl('/llms-full.txt');
  const q = query.trim().toLowerCase();
  return (
    <nav className={clsx(styles.sidebar, 'cp-touch')} aria-label="Docs pages">
      <div className={styles.filter}>
        <input
          className={styles.input}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Filter pages"
          aria-label="Filter pages"
        />
        <span className={styles.lens} aria-hidden="true" />
      </div>
      {groupsOf(sidebar).map((group) => {
        const links = group.links.filter((link) => !q || link.label.toLowerCase().includes(q));
        const open = q ? links.length > 0 : !closed[group.label];
        return (
          <div key={group.label} className={styles.group}>
            <button
              type="button"
              className={styles.category}
              aria-expanded={open}
              onClick={() => setClosed({ ...closed, [group.label]: !closed[group.label] })}
            >
              <span>{group.label}</span>
              <span className={clsx(styles.chevron, open && styles.chevronOpen)} />
            </button>
            {open && (
              <div className={styles.links}>
                {links.map((link) => {
                  const active = samePath(link.href, path);
                  return (
                    <Link
                      key={link.href}
                      to={link.href}
                      aria-current={active ? 'page' : undefined}
                      className={clsx(styles.link, active && styles.linkActive)}
                    >
                      <span className={styles.bar} />
                      {link.label}
                    </Link>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
      <div className={styles.agents}>
        <div className={styles.agentsTitle}>Docs for agents</div>
        <span>The whole site as plain text: </span>
        <a href={llms} className={styles.agentsLink}>
          llms-full.txt
        </a>
      </div>
    </nav>
  );
}
